    dsn,
    environment: import.meta.env.MODE,
    sendDefaultPii: false,
    tracesSampleRate: import.meta.env.PROD ? 0.2 : 0,
  });
} else if (import.meta.env.DEV) {
  console.warn("VITE_SENTRY_DSN is not set; error reporting is disabled.");
}

